import * as os from 'os'
import { getVersionInput, getGithubTokenInput } from './inputs'
import {
  CMD_NAME,
  OWNER,
  REPO,
  TOOL_CACHE_NAME,
  RETRY_COUNT
} from './constants'
import { exec } from 'child_process'

// `@actions/core` v3+ and `@actions/tool-cache` v4+ are ESM-only, so they must
// be loaded via dynamic import to remain consumable from this CommonJS bundle
// (and from Jest).
const loadCore = async (): Promise<typeof import('@actions/core')> =>
  await import('@actions/core')
const loadToolCache = async (): Promise<typeof import('@actions/tool-cache')> =>
  await import('@actions/tool-cache')

export const setupShfmt = async (): Promise<void> => {
  const core = await loadCore()
  const tc = await loadToolCache()
  const version = await getVersion(await getVersionInput())

  let toolPath = tc.find(
    TOOL_CACHE_NAME,
    version,
    translateArchToDistArchName()
  )
  if (toolPath) {
    core.info(`Found in cache @ ${toolPath}`)
  } else {
    const fileName = `${TOOL_CACHE_NAME}_v${version}_${translateOsPlatformToDistPlatformName()}_${translateArchToDistArchName()}`
    const downloadPath = await tc.downloadTool(
      `${getDownloadBaseUrl(version)}/${fileName}${translateOsPlatformToDistPlatformName() === 'windows' ? '.exe' : ''}`
    )
    toolPath = await tc.cacheFile(
      downloadPath,
      CMD_NAME,
      TOOL_CACHE_NAME,
      version,
      translateArchToDistArchName()
    )
    core.info(`Downloaded to ${toolPath}`)
  }

  // Add file permission to toolPath/CMD_NAME
  exec(`chmod +x "${toolPath}/${CMD_NAME}"`)

  core.addPath(toolPath)
}

interface ReleaseResponse {
  tag_name: string
}

/**
 * Get the version of shfmt to download
 * @param version 'latest' or 'x.y.z'
 * @returns 'x.y.z'
 */
const getVersion = async (version: string): Promise<string> => {
  switch (version) {
    case 'latest': {
      const core = await loadCore()
      const githubTokenInput = await getGithubTokenInput()
      // curl -s https://api.github.com/repos/${OWNER}/${REPO}/releases/latest | jq -r '.tag_name'
      const response = await (async () => {
        for (let i = 0; i < RETRY_COUNT; i++) {
          try {
            const res = await fetch(
              `https://api.github.com/repos/${OWNER}/${REPO}/releases/latest`,
              {
                headers: githubTokenInput
                  ? {
                      Authorization: `Bearer ${githubTokenInput}`
                    }
                  : undefined
              }
            )
            if (res.status !== 200) {
              throw new Error(
                `Fetching the latest release page (${res.statusText})`
              )
            }
            return res
          } catch (error) {
            core.warning(
              `${(error as Error).message} Retry... ${i + 1}/${RETRY_COUNT}`
            )
            await new Promise(resolve => setTimeout(resolve, 2000))
          }
        }
        throw new Error(
          `Failed to get the latest version. If the reason is rate limit, please set the github-token. https://github.com/actions/runner-images/issues/602`
        )
      })()
      const releaseResponse: ReleaseResponse =
        (await response.json()) as ReleaseResponse
      const tagName: string = releaseResponse.tag_name
      if (typeof tagName !== 'string') {
        throw new Error('Failed to get the latest version of shfmt.')
      }
      return tagName.replace(/^v/, '')
    }
    default:
      return version
  }
}

export const getDownloadBaseUrl = (version: string): URL => {
  switch (version) {
    case 'latest':
      return new URL(
        `https://github.com/${OWNER}/${REPO}/releases/latest/download`
      )
    default:
      return new URL(
        `https://github.com/${OWNER}/${REPO}/releases/download/v${version}`
      )
  }
}

const translateOsPlatformToDistPlatformName = (): string => {
  switch (os.platform()) {
    case 'win32':
      return 'windows'
    case 'darwin':
      return 'darwin'
    case 'linux':
      return 'linux'
    default:
      throw new Error(`Unsupported platform: ${os.platform()}.`)
  }
}

/**
 *
 * os.arch(): 'arm', 'arm64', 'ia32', 'loong64', 'mips', 'mipsel', 'ppc', 'ppc64', 'riscv64', 's390', 's390x', and 'x64'
 * ->
 * shfmt_v3.10.0_darwin_amd64
 * shfmt_v3.10.0_darwin_arm64
 * shfmt_v3.10.0_linux_386
 * shfmt_v3.10.0_linux_amd64
 * shfmt_v3.10.0_linux_arm
 * shfmt_v3.10.0_linux_arm64
 * shfmt_v3.10.0_windows_386.exe
 * shfmt_v3.10.0_windows_amd64.exe
 *
 * @param arch
 * @returns
 */
const translateArchToDistArchName = (): string => {
  switch (os.arch()) {
    case 'x64':
      return 'amd64'
    case 'arm64':
      return 'arm64'
    case 'arm':
      return 'arm'
    case 'ia32':
      return '386'
    default:
      throw new Error(
        `Unsupported architecture: ${os.arch()}. Use go install instead.`
      )
  }
}
